    public function imput($service_imput, $matricule) {

        $qb = $this->createQueryBuilder('i')
                ->addSelect('(CASE WHEN t.etataff IS NOT NULL THEN t.etataff ELSE 0 END )as etat, (CASE WHEN r.courrier IS NOT NULL THEN 1 ELSE 0 END )as etat_r, (CASE WHEN tmp.idImput IS NOT NULL THEN 1 ELSE 0 END )as etat_trait ')
                ->innerJoin('i.courrier', 'c')
                ->leftJoin('EdiligenceBundle:Treception', 'r', Join::WITH, 'i.id = r.idImput')
                ->leftJoin('EdiligenceBundle:Ttraitement', 't', Join::WITH, 'i.id = t.idImput')
                ->leftJoin('EdiligenceBundle:Tmp_traitement', 'tmp', Join::WITH, 'i.id = tmp.idImput')
                ->where("c.etatcourrier = :etatcourrier And i.serviceImput = :serviceImput And i.matriculeImput = :matriculeImput And c.etataff = :etataff ")
                ->setParameter("etatcourrier", 1)
                ->setParameter("etataff", 0)
                ->setParameter("serviceImput", $service_imput)
                ->setParameter("matriculeImput", $matricule)
                ->orderBy('i.id', 'DESC');
        //->getMaxResults(1);
        return $qb->getQuery()->getResult();
    }

    public function reception($service_sup) {
        $tab_imput = explode(',', $service_sup['tab_imput']);

        $rec = $this->getEntityManager()->createQueryBuilder()
                        ->from('EdiligenceBundle:Treception', 'r')
                        ->select('r.idImput')
                        ->where("r.servicereception =:service")
                        ->setParameter("service", $service_sup['service'])
                        ->getQuery()->getArrayResult();
        //var_dump($rec);

        $qb = $this->createQueryBuilder('i')
                ->innerJoin('i.courrier', 'c')
                ->innerJoin('EdiligenceBundle:TimputDir', 't', Join::WITH, 'i.id = t.imputation')
                //->leftJoin('EdiligenceBundle:Treception', 'r',  Join::WITH,'c.id = r.courrier')
                ->where('c.etatcourrier = :etatcourrier And i.etatImput >= :etatImput And i.etatTrait >= :etatTrait And t.serviceImput In(:serviceImput) ') //And c.etatReception In (:etatReception)And (r.etatreception = 0 or r.courrier is null or r.etatreception is null )
                ->andWhere('c.typecourrier =:typecourrier')
                ->setParameter('typecourrier', 1);
        if ($rec != null) {
            $qb->andWhere('i.id not in(:rec)')
                    ->setParameter("rec", $rec);
        }
        $qb->setParameter("etatcourrier", 1)
                ->setParameter("etatImput", 0)
                ->setParameter("etatTrait", 0)
                //->setParameter("etatReception", array(0,1))
                ->setParameter("serviceImput", $tab_imput);
        //var_dump($qb->getQuery()); die;
        //var_dump($qb->getParameters()); die;;
        //  var_dump($qb->getQuery()->getResult());
        //  die;
        return $qb->getQuery()->getResult();
    }

    public function traiter_cs($matuser) {
        $qb = $this->createQueryBuilder('i')
                ->select("t.serviceImput, i, i.id, i.dateImput, i.delaiImput, c.objet, c.sourceCour, r.etatreception,(case when i.coordinateur = '" . $matuser . "' then 1 else 0 end)as coord, i.nbrePers ")
                ->innerJoin("EdiligenceBundle:TimputDir", 't', Join::WITH, 'i.id = t.imputation')
                ->innerJoin("EdiligenceBundle:Tcourrier", 'c', Join::WITH, 'i.courrier = c.id')
                ->innerJoin('EdiligenceBundle:Treception', 'r', Join::WITH, 'r.servicereception = i.serviceImput')
                ->innerJoin('AgentBundle:Agent', 'a', Join::WITH, 't.serviceImput = a.matricule')
                ->innerJoin('AgentBundle:Pj', 'p', Join::WITH, 'c.piecejointe = p.id')
                ->leftJoin('EdiligenceBundle:Tmp_traitement', 'tmp', Join::WITH, 'i.id = tmp.idImput')
                ->where('i.etatImput >= :etatImput And t.serviceImput =:serviceImput And t.serviceImput <> t.matriculeimpute')
                ->setParameter("etatImput", 1)
                ->setParameter("serviceImput", $matuser);

        return $qb->getQuery()->getResult();
    }

    public function csrecu_traiter($service, $mat) {
        $qb = $this->createQueryBuilder('i')
                // ->select("t.serviceImput, i, i.id, i.dateImput, i.delaiImput, c.objet, c.sourceCour, c.adresseenreg, r.etatreception,(case when (i.coordinateur = '".$service."' or i.coordinateur = '".$mat."'  ) then 1 else 0 end)as coord, i.nbrePers, tmp.librejet  ")
                ->select("i, t.serviceImput, r.etatreception,(case when (i.coordinateur = '" . $service . "' or i.coordinateur = '" . $mat . "'  ) then 1 else 0 end)as coord, tmp.librejet")
                ->innerJoin("EdiligenceBundle:TimputDir", 't', Join::WITH, 'i.id = t.imputation')
                ->innerJoin('i.courrier', 'c')
                ->leftJoin('EdiligenceBundle:Treception', 'r', Join::WITH, 'i.id = r.idImput And r.servicereception = t.serviceImput')
                ->leftJoin('EdiligenceBundle:Tmp_traitement', 'tmp', Join::WITH, 't.id = tmp.imputdir And tmp.matriculeimpute = t.matriculeimpute')
                ->where('i.etatTrait >= :etatTrait And c.etatcourrier = :etatcourrier And c.etataff >= :etataff and (tmp.imputdir is null or tmp.etattraitement >= 0)')
                ->setParameter("etatTrait", 0)
                ->setParameter("etatcourrier", 1)
                ->setParameter("etataff", 0)
                ->andWhere("(i.serviceImput <>'" . $service . "' Or i.serviceImput <>'" . $mat . "')")
                ->andWhere("t.serviceImput='" . $service . "' Or t.serviceImput='" . $mat . "' ")
                ->andwhere("t.desactive=:desactive")
                ->setParameter("desactive", 0)
                ->andWhere("i.etatImput >= 0 ")
                ->andWhere("t.etatImputDir >=:etatImputDir")
                ->setParameter("etatImputDir", 0);

        return $qb->getQuery()->getResult();
    }

