    public function dilig_impute($service, $matricule) {
        $qb = $this->createQueryBuilder('i')
                ->select('c.objet, i.id as imput, i.dateImput, t.serviceImput, a.nom, a.prenoms, a.nomJeuneFille, i.serviceImput as mat, tmp.id as etat, p as piecejointe')
                ->innerJoin("EdiligenceBundle:TimputDir", 't', Join::WITH, 'i.id = t.imputation and t.desactive >= 0')
                ->innerJoin("EdiligenceBundle:Tcourrier", 'c', Join::WITH, 'i.courrier = c.id')
                ->leftJoin('EdiligenceBundle:Treception', 'r', Join::WITH, 'r.servicereception = i.serviceImput')
                ->innerJoin('AgentBundle:Agent', 'a', Join::WITH, 't.serviceImput = a.matricule')
                ->innerJoin('AgentBundle:Pj', 'p', Join::WITH, 'c.piecejointe = p.id')
                ->leftJoin('EdiligenceBundle:Tmp_traitement', 'tmp', Join::WITH, 'i.courrier = tmp.codecourrier')
                ->where('i.etatImput >:etatImput And i.etatTrait >= :etatTrait ')
                ->andWhere('t.imputMatricule=:imputMatricule')
                //->andWhere("t.serviceImput <>'".$service."' Or t.serviceImput <>'".$matricule."' ")

                /*   ->andWhere('i.serviceImput=:serviceImput And t.serviceImput <>:imputMatricule')
                  ->setParameter("serviceImput", $service)
                  ->setParameter("imputMatricule", $matricule)
                  ->setParameter("etatImputDir", 0) */
                ->setParameter("etatImput", 0)
                ->setParameter("imputMatricule", $matricule)
                ->setParameter("etatTrait", 0);
        //dump($qb->getQuery()); die;
        return $qb->getQuery()->getResult();
    }

    public function findimput($service, $mat, $codecourrier) {
        $qb = $this->createQueryBuilder('i')
                ->select('i, t.id as imputdirs')
                ->distinct()
                ->innerJoin("EdiligenceBundle:TimputDir", 't', Join::WITH, 'i.id = t.imputation and t.desactive = 1')
                ->where('i.etatTrait >=:etatTrait')
                ->andWhere('i.courrier =:codecourrier')
                ->andWhere("t.serviceImput ='" . $service . "' Or t.serviceImput ='" . $mat . "'")
                ->setParameter('codecourrier', $codecourrier)
                ->setParameter('etatTrait', 0);
        // dump($qb->getQuery()); die;
        return $qb->getQuery()->getResult();
    }

    public function cumul($courrier) {
        $qb = $this->createQueryBuilder('i')
                ->select('count(i.courrier) as nbre')
                ->where('i.courrier =:courrier')
                ->setParameter('courrier', $courrier);

        return $qb->getQuery()->getResult();
    }

    public function jauge($dateimput, $delai, $datejour) {
        $delais = $delai->getTimestamp();
        $init = $dateimput->getTimestamp();
        $now = $datejour->getTimestamp();
        $inter = $delais - $init;
      
        if ($inter <= 0) {
            $parcour = 100;
        } else {
            $interp = 100;
            $parcour = (($now - $init) / $inter) * 100;

            if ($parcour > 100) {
                $parcour = 100;
            }

            if ($parcour < 0) {
                $parcour = 0;
            }
        }
        $parcouru = round($parcour, 2);
        $inter = round($inter, 2);
        $class = '';
        if ($parcouru >= 100) {
            $class = "progress-bar bg-danger";
        } elseif ($parcouru >= 75) {
            $class = "progress-bar bg-warning";
        } elseif ($parcouru >= 50) {
            $class = "progress-bar bg-info";
        } else {
            $class = "progress-bar bg-success";
        }


        $div = '<div class="progress"><div class="' . $class . '" role="progressbar" style="width: ' . $parcouru . '%" aria-valuenow="' . $parcouru . '" aria-valuemin="0" aria-valuemax="100"></div></div>';
        return $div;
    }

